/**
 * Behaviour against REAL records generated by the upstream AI-DLC engine
 * (2.10.0, 2.11.4, 2.11.5-preview.20261114.1). See test/fixtures/upstream/README.md
 * for how they were produced. Expectations here are what the records say,
 * checked by hand against the raw files, not what the parser happens to emit.
 */
import { describe, expect, it } from "vitest";
import { FIX, intentsOf, scan } from "./helpers.js";

describe("populated 2.11.4 workspace (2 spaces, 4 intents)", async () => {
  const r = await scan(FIX("populated"));
  const byDir = new Map(intentsOf(r).map((i) => [i.dirName, i]));

  it("detects installation, adapter and verified compatibility", () => {
    expect(r.snapshot.installations.map((i) => [i.harnessDir, i.frameworkVersion, i.distribution])).toEqual([[".claude", "2.11.4", "claude"]]);
    expect(r.snapshot.compatibility.adapterId).toBe("aidlc-records-v2");
    expect(r.snapshot.compatibility.level).toBe("verified");
  });

  it("lists spaces from disk, not a fixed list", () => {
    expect(r.snapshot.spaces.map((s) => s.name)).toEqual(["default", "payments-team"]);
    expect(r.snapshot.spaces.find((s) => s.name === "payments-team")?.active).toBe(true);
  });

  it("reads lifecycle from the registry and progress from the stage checklist", () => {
    const done = byDir.get("261115-version-flag")!;
    expect(done.lifecycle).toBe("complete");
    expect(done.progress).toMatchObject({ completed: 9, planned: 9, mismatch: null });
    expect(done.currentStage).toBeNull();

    const bug = byDir.get("261115-csv-export-timeout")!;
    expect(bug.scope).toBe("bugfix");
    expect(bug.progress).toMatchObject({ completed: 4, planned: 8 });
    expect(bug.currentStage?.slug).toBe("code-generation");
  });

  it("reports pending decisions only from evidence", () => {
    expect(byDir.get("261115-csv-export-timeout")!.pending.map((p) => [p.kind, p.stage])).toEqual([["plan-approval", "code-generation"]]);
    expect(byDir.get("261115-refund-idempotency")!.pending.map((p) => [p.kind, p.stage])).toEqual([["approval-gate", "code-generation"]]);
    expect(byDir.get("261115-inventory-api")!.pending).toEqual([]);
    expect(byDir.get("261115-version-flag")!.pending).toEqual([]);
  });

  it("derives workflow structure from the record: phases in order, no hardcoded count", () => {
    const d = r.details.get("default/261115-csv-export-timeout")!;
    expect(d.phases.map((p) => p.id)).toEqual(["initialization", "ideation", "inception", "construction", "operation"]);
    const stages = d.phases.flatMap((p) => p.stages);
    expect(stages).toHaveLength(33);
    expect(stages.filter((s) => s.inPlan)).toHaveLength(8);
    expect(stages.find((s) => s.slug === "requirements-analysis")).toMatchObject({ state: "completed", revisionCount: 1, name: "Requirements Analysis", number: "2.3" });
    expect(stages.find((s) => s.slug === "market-research")?.state).toBe("not-in-plan");
    expect(stages.find((s) => s.slug === "build-and-test")?.state).toBe("pending");
  });

  it("keeps decisions, answers, person's words and gate outcomes as recorded", () => {
    const d = r.details.get("default/261115-csv-export-timeout")!;
    const q1 = d.decisions.find((x) => x.title.startsWith("Q1:"))!;
    expect(q1.options).toEqual(["Keep 30s but stream rows (Recommended)", "Raise to 120s"]);
    expect(q1.recommended).toBe("Keep 30s but stream rows");
    expect(q1.answerState).toBe("answered");
    const ans = d.decisions.find((x) => x.id === q1.answeredBy)!;
    expect(ans).toMatchObject({ choice: "Keep 30s but stream rows", personReply: "Stream the rows and keep 30 seconds" });
    const rejected = d.decisions.find((x) => x.kind === "gate-rejected")!;
    expect(rejected.personReply).toContain("retry behaviour");
    expect(rejected.gitName).toBe("Demo Dev");
    expect(d.decisions.find((x) => x.kind === "gate-approved")?.choice).toBe("Approve");
    // New-work routing ask is closed by REQUEST_ROUTED naming its id, not left pending.
    const routing = d.decisions.find((x) => x.eventType === "QUESTION_ASKED" && /new request/i.test(x.title))!;
    expect(routing.answerState).toBe("answered");
  });

  it("flags unresolved automated check findings on the in-progress stage", () => {
    const d = r.details.get("default/261115-inventory-api")!;
    const us = d.phases.flatMap((p) => p.stages).find((s) => s.slug === "user-stories")!;
    expect(us.state).toBe("in-progress");
    expect(us.attention.some((a) => a.kind === "check-findings")).toBe(true);
  });

  it("lists artifacts per stage, excluding hidden engine folders", () => {
    const d = r.details.get("default/261115-csv-export-timeout")!;
    const names = d.artifacts.filter((a) => a.stage === "requirements-analysis").map((a) => a.name);
    expect(names).toContain("requirements.md");
    expect(d.artifacts.every((a) => !a.path.includes("/.aidlc-"))).toBe(true);
    expect(d.artifacts.find((a) => a.name === "requirements.md")?.recorded).toBe(true);
  });

  it("parses every audit event with a timestamp and knows the installed vocabulary", () => {
    const d = r.details.get("default/261115-csv-export-timeout")!;
    const events = d.events.filter((e) => e.type !== "NOTE");
    expect(events.length).toBeGreaterThan(50);
    expect(events.every((e) => e.timestamp && e.known)).toBe(true);
    // Single writer: nothing is cross-writer unordered.
    expect(events.some((e) => e.unordered)).toBe(false);
  });
});

describe("customized workflow (test-pro plugin stages)", async () => {
  const r = await scan(FIX("custom"));
  const d = r.details.get("default/261115-checkout-validation")!;
  it("shows plugin stages in their recorded phases and marks them custom", () => {
    const stages = d.phases.flatMap((p) => p.stages);
    expect(stages).toHaveLength(35);
    const integ = stages.find((s) => s.slug === "test-pro-integration")!;
    expect(integ).toMatchObject({ phaseId: "construction", state: "awaiting-approval", custom: true, name: "Cross-Unit Integration Testing" });
    expect(stages.find((s) => s.slug === "test-pro-full-suite")).toMatchObject({ phaseId: "operation", state: "pending", custom: true });
    expect(d.scope).toBe("test-pro-validation");
    expect(d.pending.map((p) => p.stage)).toEqual(["test-pro-integration"]);
  });
});

describe("empty workspace (configured, no intents)", async () => {
  const r = await scan(FIX("empty-configured"));
  it("is detected and genuinely empty, not missing", () => {
    expect(r.snapshot.compatibility.level).toBe("verified");
    expect(intentsOf(r)).toEqual([]);
    expect(r.snapshot.spaces.map((s) => [s.name, s.registry.status])).toEqual([["default", "missing"]]);
  });
});

describe("independent upstream upgrade / downgrade / preview", async () => {
  const v210 = await scan(FIX("v2100"));
  const upgraded = await scan(FIX("upgraded"));
  const downgraded = await scan(FIX("downgraded"));
  const preview = await scan(FIX("preview"));
  const populated = await scan(FIX("populated"));

  it("reports the version each project is configured with", () => {
    expect(v210.snapshot.installations[0].frameworkVersion).toBe("2.10.0");
    expect(upgraded.snapshot.installations[0].frameworkVersion).toBe("2.11.4");
    expect(downgraded.snapshot.installations[0].frameworkVersion).toBe("2.10.0");
    expect(preview.snapshot.installations[0].frameworkVersion).toBe("2.11.5-preview.20261114.1");
    for (const s of [v210, upgraded, downgraded, preview]) expect(s.snapshot.compatibility.level).toBe("verified");
  });

  it("reads 2.10.0-written records identically after the project is refreshed to 2.11.4", () => {
    const a = v210.details.get("default/261115-health-endpoint")!;
    const b = upgraded.details.get("default/261115-health-endpoint")!;
    const shape = (d: typeof a) => d.phases.flatMap((p) => p.stages.map((s) => [s.slug, s.state]));
    expect(shape(b)).toEqual(shape(a));
    expect(b.pending).toEqual(a.pending);
    expect(a.pending.map((p) => [p.kind, p.stage])).toEqual([["approval-gate", "build-and-test"]]);
  });

  it("after a downgrade, archived intents keep their record and stop asking for decisions", () => {
    const arch = intentsOf(downgraded).filter((i) => i.lifecycle === "archived");
    expect(arch.map((i) => i.dirName).sort()).toEqual(["261115-csv-export-timeout", "261115-inventory-api", "261115-refund-idempotency"]);
    expect(arch.every((i) => i.pending.length === 0)).toBe(true);
  });

  it("a preview runtime over 2.11.4 records yields the same intent data", () => {
    const strip = (r: typeof populated) => intentsOf(r).map((i) => [i.dirName, i.lifecycle, i.progress?.completed, i.pending.length]);
    expect(strip(preview)).toEqual(strip(populated));
  });
});

describe("demo workspace (synthetic content, real engine records)", async () => {
  const r = await scan(FIX("../../../demo/workspace"));
  it("loads through the same adapter", () => {
    expect(intentsOf(r).length).toBe(3);
    expect(r.snapshot.compatibility.adapterId).toBe("aidlc-records-v2");
  });
});
